using System.Text.Json.Nodes;
using Modeller.Core;
namespace Modeller.Application;

public sealed class ReviewGovernance(SnapshotRepository repository,ModellingIdentity actor,StandardsGateway engine)
{
    private static string S(JsonObject o,string k,string fallback="")=>KnowledgeCorpus.Text(o,k,fallback);
    private static readonly Dictionary<string,string[]> Transitions=new(StringComparer.Ordinal){["DRAFT"]=["REVIEW_REQUESTED"],["VALIDATED"]=["REVIEW_REQUESTED"],["REVIEW_REQUESTED"]=["REVIEWED","CHANGES_REQUESTED"],["REVIEWED"]=["APPROVED","CHANGES_REQUESTED"],["CHANGES_REQUESTED"]=["DRAFT"],["APPROVED"]=["PUBLISHED","CHANGES_REQUESTED"],["PUBLISHED"]=["DEPRECATED"],["DEPRECATED"]=[]};
    private static void Enabled(){if(Environment.GetEnvironmentVariable("GOVERNANCE_ENABLED")!="true")throw new ProcessingException("GOVERNANCE_NOT_CONFIGURED");}
    private void Write(string project){actor.Write(project);if(!(actor.Roles??[]).Contains("modeller"))throw new ProcessingException("GOVERNANCE_MODELLER_REQUIRED");}
    private static void Comment(string comment){if(string.IsNullOrWhiteSpace(comment)||comment.Length>4000||comment.Any(c=>char.IsControl(c)&&c is not ('\r' or '\n' or '\t')))throw new ProcessingException("GOVERNANCE_COMMENT_REQUIRED");}
    public JsonObject View(AuditLedger ledger,string subject,bool includeContent=false){
        var events=ledger.Events(actor.Tenant,subject);if(events.Count==0||S((JsonObject)events[0]!,"type")!="REGISTER")throw new ProcessingException("GOVERNANCE_SUBJECT_NOT_FOUND");var first=(JsonObject)events[0]!;var last=(JsonObject)events[^1]!;var source=(JsonObject)first["source"]!;actor.Read(S(source,"project"));JsonObject? validation=null;string? digest=null;
        foreach(var e in events.OfType<JsonObject>())if(S(e,"type")=="VALIDATION"){validation=e["validation"]?.DeepClone() as JsonObject;digest=S(e,"validation_digest");}
        var current=false;JsonObject? artifact=null;try{artifact=repository.Artifact(S(source,"project"),S(source,"path"));current=S(artifact,"revision")==S(source,"revision")&&S(artifact,"sha256")==S(source,"sha256")&&Data.Hash(S(artifact,"content"))==S(source,"sha256");}catch(ProcessingException){}
        var state=S(last,"new_state");var view=new JsonObject{["subject"]=subject,["sequence"]=events.Count,["state"]=state,["author"]=first["author"]!.DeepClone(),["source"]=source.DeepClone(),["validation"]=validation,["validation_digest"]=digest,["events"]=events,["current_source"]=current,["clinical_approval"]=state is "APPROVED" or "PUBLISHED",["approval_scope"]="The exact recorded source revision, never a newer revision."};
        var available=new JsonArray();foreach(var next in Transitions.GetValueOrDefault(state,[])){try{Policy(view,next,null,false);if(current||next=="DEPRECATED")available.Add(next);}catch(ProcessingException){}}
        view["available_transitions"]=available;if(includeContent){var old=repository.Artifact(S(source,"project"),S(source,"path"),S(source,"revision"));if(S(old,"sha256")!=S(source,"sha256")||Data.Hash(S(old,"content"))!=S(source,"sha256"))throw new ProcessingException("GOVERNANCE_SOURCE_INTEGRITY_FAILED");view["content"]=old["content"]?.DeepClone();}return view;
    }
    public async Task<JsonObject> Execute(string name,JsonObject args,CancellationToken cancellation){
        Enabled();using var ledger=new AuditLedger();
        if(name=="governance_list"){var project=Data.Required(args,"project");actor.Read(project);var count=KnowledgeCorpus.Number(args,"count",25);var offset=KnowledgeCorpus.Number(args,"offset",0);var records=ledger.Subjects(actor.Tenant,project,count,offset,"REGISTER");var items=new JsonArray(records.OfType<JsonObject>().Select(r=>(JsonNode)new JsonObject{["subject"]=r["subject"]!.DeepClone(),["sequence"]=r["sequence"]!.DeepClone(),["state"]=r["latest"]!["new_state"]!.DeepClone(),["source"]=r["first"]!["source"]!.DeepClone(),["author"]=r["first"]!["author"]!.DeepClone(),["updated_at"]=r["latest"]!["timestamp"]!.DeepClone()}).ToArray());return new JsonObject{["items"]=items,["count"]=count,["offset"]=offset,["has_more_possible"]=items.Count==count};}
        if(name=="governance_prepare"){
            var project=Data.Required(args,"project");Write(project);Comment(S(args,"comment"));if(S(repository.Project(project),"status")!="ACTIVE")throw new ProcessingException("GOVERNANCE_PROJECT_ARCHIVED");var artifact=repository.Artifact(project,Data.Required(args,"path"));if(S(artifact,"revision")!=S(args,"modelRevision"))throw new ProcessingException("MODEL_REVISION_CONFLICT");var identity=new JsonObject{["project"]=project,["path"]=args["path"]!.DeepClone(),["revision"]=artifact["revision"]!.DeepClone(),["sha256"]=artifact["sha256"]!.DeepClone()};var subject=Data.Hash(HistoricJson.Encode(identity));
            if(ledger.Events(actor.Tenant,subject).Count==0)ledger.Append(actor.Tenant,subject,0,new JsonObject{["type"]="REGISTER",["project"]=project,["source"]=identity,["author"]=actor.Id,["actor"]=Imports.Actor(actor),["previous_state"]=null,["new_state"]="DRAFT",["comment"]=args["comment"]!.DeepClone()});return View(ledger,subject);
        }
        var id=Data.Required(args,"subject");var view=View(ledger,id);if(name=="governance_get")return view;var source=(JsonObject)view["source"]!;Write(S(source,"project"));var expected=args["expectedSequence"]!.GetValue<int>();if(view["sequence"]!.GetValue<int>()!=expected)throw new ProcessingException("GOVERNANCE_REVISION_CONFLICT");if(view["current_source"]?.GetValue<bool>()!=true)throw new ProcessingException("GOVERNANCE_SOURCE_CHANGED");
        if(name=="governance_validate"){
            if(S(view,"state") is "APPROVED" or "PUBLISHED" or "DEPRECATED")throw new ProcessingException("GOVERNANCE_VALIDATION_STATE_FORBIDDEN");var artifact=repository.Artifact(S(source,"project"),S(source,"path"),S(source,"revision"));var ext=System.IO.Path.GetExtension(S(source,"path")).TrimStart('.');var format=ext is "oet" or "opt" or "adl" or "aql"?ext:"xml";var report=await ModelChecks.Quality(new JsonObject{["content"]=S(artifact,"content"),["format"]=format},engine,cancellation);var digest=Data.Hash(HistoricJson.Encode(report,false));ledger.Append(actor.Tenant,id,expected,new JsonObject{["type"]="VALIDATION",["project"]=S(source,"project"),["actor"]=Imports.Actor(actor),["previous_state"]=view["state"]!.DeepClone(),["new_state"]=Qualified(report,S(source,"sha256"))?"VALIDATED":"DRAFT",["comment"]="Deterministic validation executed; previous decisions do not apply to new evidence.",["validation"]=report,["validation_digest"]=digest});return View(ledger,id);
        }
        return Transition(ledger,id,expected,name=="governance_request_review"?"REVIEW_REQUESTED":name=="governance_reopen_draft"?"DRAFT":throw new ProcessingException("GOVERNANCE_OPERATION_UNSUPPORTED"),S(args,"comment"),null);
    }
    public JsonObject HumanTransition(string subject,int expected,string state,string comment,string? digest){Enabled();using var ledger=new AuditLedger();return Transition(ledger,subject,expected,state,comment,digest);}
    private JsonObject Transition(AuditLedger ledger,string subject,int expected,string to,string comment,string? digest){Comment(comment);var view=View(ledger,subject);var source=(JsonObject)view["source"]!;actor.Write(S(source,"project"));if(view["sequence"]!.GetValue<int>()!=expected)throw new ProcessingException("GOVERNANCE_REVISION_CONFLICT");Policy(view,to,digest,true);if(to!="DEPRECATED"&&view["current_source"]?.GetValue<bool>()!=true)throw new ProcessingException("GOVERNANCE_SOURCE_CHANGED");ledger.Append(actor.Tenant,subject,expected,new JsonObject{["type"]="TRANSITION",["project"]=S(source,"project"),["actor"]=Imports.Actor(actor),["previous_state"]=view["state"]!.DeepClone(),["new_state"]=to,["comment"]=comment,["validation_digest"]=view["validation_digest"]?.DeepClone()});return View(ledger,subject);}
    private void Policy(JsonObject view,string to,string? digest,bool confirm){if(!Transitions.GetValueOrDefault(S(view,"state"),[]).Contains(to))throw new ProcessingException("GOVERNANCE_INVALID_TRANSITION");actor.Write(S((JsonObject)view["source"]!,"project"));if(to is "REVIEWED" or "CHANGES_REQUESTED" or "APPROVED" or "PUBLISHED" or "DEPRECATED"){
            var role=to=="APPROVED"?"approver":to is "PUBLISHED" or "DEPRECATED"?"publisher":"reviewer";if(!actor.Human||actor.Id==S(view,"author")||!(actor.Roles??[]).Contains(role))throw new ProcessingException("GOVERNANCE_INDEPENDENT_HUMAN_REQUIRED");
        }else if(!(actor.Roles??[]).Contains("modeller"))throw new ProcessingException("GOVERNANCE_MODELLER_REQUIRED");
        if(to is "APPROVED" or "PUBLISHED"){if(!Qualified(view["validation"] as JsonObject,S((JsonObject)view["source"]!,"sha256")))throw new ProcessingException("GOVERNANCE_VALIDATION_REQUIRED");if(confirm&&(digest is null||digest!=S(view,"validation_digest")))throw new ProcessingException("GOVERNANCE_VALIDATION_CONFIRMATION_REQUIRED");}
    }
    public static bool Qualified(JsonObject? report,string hash){if(report is null||S(report,"status")!="PASS"||report["release_eligible"]?.GetValue<bool>()!=true||S(report,"content_sha256")!=hash||report["steps"] is not JsonArray{Count:>0} steps)return false;var seen=new Dictionary<string,string>(StringComparer.Ordinal);foreach(var step in steps.OfType<JsonObject>()){var name=S(step,"name");var status=S(step,"status");if(!seen.TryAdd(name,status)||status is not ("PASS" or "NOT_APPLICABLE")||status=="NOT_APPLICABLE"&&string.IsNullOrWhiteSpace(S(step,"reason")))return false;}return new[]{"parse","structure","semantics","openehr_conformance","repository_policy","requirements_traceability"}.All(n=>seen.GetValueOrDefault(n)=="PASS")&&seen.ContainsKey("dependencies")&&seen.ContainsKey("terminology");}
}
public static class HistoricJson
{
    public static string Encode(JsonNode value,bool slashEscapes=true){var text=value.ToJsonString(new System.Text.Json.JsonSerializerOptions{Encoder=System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping});var result=new System.Text.StringBuilder();foreach(var c in text){if(c>127)result.Append("\\u").Append(((int)c).ToString("x4",System.Globalization.CultureInfo.InvariantCulture));else if(c=='/'&&slashEscapes)result.Append("\\/");else result.Append(c);}return result.ToString();}
}
